CREATE OR REPLACE FUNCTION public.rsc_check_condition_decision_seal(checked_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.stock_condition_decision_seals%ROWTYPE; prepared jsonb; key text; members uuid[]; body jsonb;
BEGIN
    SELECT * INTO s FROM public.stock_condition_decision_seals WHERE id=checked_id;
    IF s.id IS NULL THEN RAISE EXCEPTION 'condition exact seal required' USING ERRCODE='23514'; END IF;
    prepared:=public.rsc_condition_decision_seal_source(s.command_jsonb);
    FOREACH key IN ARRAY ARRAY['kind','command_jsonb','request_id','reason','request_hash','idempotency_key_hash',
        'root_disposition_id','inbound_id','inbound_line_id','source_account_id','original_transaction_id',
        'original_movement_id','original_ledger_cursor','case_id','expected_event_id','claimed_event_hash',
        'historical_state','historical_sequence'] LOOP
        IF to_jsonb(s)->key IS DISTINCT FROM prepared->key THEN
            RAISE EXCEPTION 'condition retained seal differs from exact source' USING ERRCODE='23514'; END IF;
    END LOOP;
    PERFORM public.rsc_condition_decision_seal_actor(s.actor_user_id,s.actor_person_id,prepared);
    IF s.created_at<(prepared->>'source_created_at')::timestamptz OR s.created_at>clock_timestamp() THEN
        RAISE EXCEPTION 'condition decision seal source person and historical time required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_condition_decision_seal_absence(s.id);
    body:=public.rsc_condition_decision_seal_payload(s.id);
    members:=public.rsc_loss_inventory_audit_members_0159();
    IF (SELECT count(*) FROM public.audit_events a WHERE (aggregate_id=s.id::text OR request_id='condition-decision-seal:'||s.id::text)
        AND public.rsc_condition_decision_seal_relevant('audit_events',to_jsonb(a)))<>1
       OR NOT EXISTS(SELECT 1 FROM public.audit_events a WHERE a.id=ANY(members) AND a.stream_key='inventory'
            AND a.aggregate_type='stock_condition_decision_seal' AND a.aggregate_id=s.id::text
            AND a.action='seal_condition_decision_request' AND a.actor_user_id=s.actor_user_id
            AND a.request_id='condition-decision-seal:'||s.id::text AND a.before_jsonb='{}'::jsonb
            AND a.created_at=s.created_at AND a.occurred_at=s.created_at
            AND public.rsc_canonical_reconciliation_json_0026(a.after_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
       OR EXISTS(SELECT 1 FROM public.state_transition_events a WHERE aggregate_id=s.id::text
            AND public.rsc_condition_decision_seal_relevant('state_transition_events',to_jsonb(a)))
       OR EXISTS(SELECT 1 FROM public.outbox_events WHERE aggregate_id=s.id::text)
       OR EXISTS(SELECT 1 FROM public.notification_events WHERE business_id=s.id::text)
       OR EXISTS(SELECT 1 FROM public.inventory_transactions WHERE source_document_id=s.id::text) THEN
        RAISE EXCEPTION 'condition decision seal requires one audit and no business effects' USING ERRCODE='23514'; END IF;
END $function$

