        'carrier',shipment.carrier,'tracking_no',shipment.tracking_no,'shipped_at',to_char(shipment.shipped_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN mod(extract(microseconds FROM shipment.shipped_at)::bigint,1000000)=0 THEN 'Z' ELSE to_char(shipment.shipped_at AT TIME ZONE 'UTC','.US"Z"') END,'recorded_at',to_char(parcel.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN mod(extract(microseconds FROM parcel.created_at)::bigint,1000000)=0 THEN 'Z' ELSE to_char(parcel.created_at AT TIME ZONE 'UTC','.US"Z"') END,'lines',package_lines);
    IF fact.plan_jsonb->'package' IS DISTINCT FROM package OR jsonb_array_length(package_lines) NOT BETWEEN 1 AND 100
