CREATE OR REPLACE FUNCTION public.rsc_condition_check_request_key(checked_event uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE e public.stock_condition_events%ROWTYPE; b public.stock_condition_request_key_bindings%ROWTYPE;
    keys text[];
BEGIN
    SELECT * INTO e FROM public.stock_condition_events WHERE id=checked_event;
    SELECT * INTO b FROM public.stock_condition_request_key_bindings WHERE event_id=checked_event;
    IF e.id IS NULL OR b.event_id IS NULL OR b.case_id IS DISTINCT FROM e.case_id
       OR b.actor_user_id IS DISTINCT FROM e.actor_user_id OR b.actor_person_id IS DISTINCT FROM e.actor_person_id
       OR b.request_id IS DISTINCT FROM e.request_id OR b.request_hash IS DISTINCT FROM e.request_hash
       OR b.created_at IS DISTINCT FROM e.created_at OR b.condition_key_hash IS DISTINCT FROM e.idempotency_key_hash THEN
        RAISE EXCEPTION 'condition exact durable request binding required' USING ERRCODE='23514'; END IF;
    SELECT array_agg(value) INTO keys FROM jsonb_each_text(to_jsonb(b)) WHERE key=ANY(ARRAY['raw_key_hash','regional_key_hash','headquarters_key_hash','disposition_key_hash','return_key_hash','reversal_key_hash','approval_key_hash','correction_key_hash','recovery_key_hash','scrap_key_hash','condition_key_hash']);
    IF EXISTS(SELECT 1 FROM public.stock_operation_orders t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (CASE WHEN e.kind='submit' THEN e.case_id END)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_dispositions t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_regional_reviews t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_headquarters_reviews t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_request_seals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_review_request_seals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_disposition_request_seals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.disposition_key_hash=ANY(keys) OR t.return_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_cancellations t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_command_seals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_outbounds t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_shipments t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_receipts t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_return_inbounds t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_return_inbound_seals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_disposition_reversals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_correction_decisions t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_correction_executions t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_inverse_request_seals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys) OR t.reversal_key_hash=ANY(keys) OR t.approval_key_hash=ANY(keys) OR t.correction_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_correction_approval_seals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys) OR t.reversal_key_hash=ANY(keys) OR t.approval_key_hash=ANY(keys) OR t.correction_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_correction_execution_seals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys) OR t.reversal_key_hash=ANY(keys) OR t.approval_key_hash=ANY(keys) OR t.correction_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_scrap_recovery_requests t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_scrap_recovery_regional_reviews t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_scrap_recovery_headquarters_reviews t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_scrap_recovery_executions t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_request_key_bindings t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.reversal_key_hash=ANY(keys) OR t.approval_key_hash=ANY(keys) OR t.correction_key_hash=ANY(keys) OR t.recovery_key_hash=ANY(keys) OR t.scrap_key_hash=ANY(keys) OR t.key_token=b.key_token) AND t.fact_id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_scrap_request_key_bindings t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.reversal_key_hash=ANY(keys) OR t.approval_key_hash=ANY(keys) OR t.correction_key_hash=ANY(keys) OR t.recovery_key_hash=ANY(keys) OR t.scrap_key_hash=ANY(keys) OR t.key_token=b.key_token) AND t.fact_id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_scrap_request_seals t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys) OR t.reversal_key_hash=ANY(keys) OR t.approval_key_hash=ANY(keys) OR t.correction_key_hash=ANY(keys) OR t.recovery_key_hash=ANY(keys) OR t.scrap_key_hash=ANY(keys) OR t.key_token=b.key_token) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_condition_events t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (e.id)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_condition_submission_requests t WHERE ((t.actor_user_id=b.actor_user_id AND t.request_id=b.request_id) OR t.idempotency_key_hash=ANY(keys)) AND t.event_id IS DISTINCT FROM (CASE WHEN e.kind='submit' THEN e.id END)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.inventory_transactions t WHERE (t.idempotency_key_hash=ANY(keys)) AND t.id IS DISTINCT FROM (NULL::uuid)) THEN RAISE EXCEPTION 'condition durable request collides with another action' USING ERRCODE='23514'; END IF;
