CREATE OR REPLACE FUNCTION public.rsc_condition_decision_seal_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE raw jsonb; body jsonb; keys text[]; matched uuid;
BEGIN
    FOR raw IN SELECT value FROM jsonb_array_elements(
        CASE WHEN TG_OP='INSERT' THEN jsonb_build_array(to_jsonb(NEW))
             WHEN TG_OP='DELETE' THEN jsonb_build_array(to_jsonb(OLD))
             ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END) LOOP
        IF NOT public.rsc_condition_decision_seal_relevant(TG_TABLE_NAME,raw) THEN CONTINUE; END IF;
        IF TG_TABLE_NAME='stock_condition_decision_seals' THEN
            PERFORM public.rsc_check_condition_decision_seal((raw->>'id')::uuid);
            PERFORM public.rsc_condition_decision_seal_authority(raw->>'actor_user_id',(raw->>'authorization_version')::bigint,
                (raw->>'actor_person_id')::uuid,raw->'command_jsonb',true);
        -- The derived audit request namespace is internal. Ordinary business
        -- request IDs use the public safe-string contract, including colons.
        ELSIF raw->>'aggregate_type'='stock_condition_decision_seal' OR raw->>'business_type'='stock_condition_decision_seal'
           OR raw->>'action'='seal_condition_decision_request'
           OR (TG_TABLE_NAME='audit_events' AND raw->>'request_id' LIKE 'condition-decision-seal:%') THEN
            IF COALESCE(raw->>'aggregate_type',raw->>'business_type') IS DISTINCT FROM 'stock_condition_decision_seal'
               OR NOT COALESCE(COALESCE(raw->>'aggregate_id',raw->>'business_id') ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$',false) THEN
                RAISE EXCEPTION 'condition decision seal effect namespace required' USING ERRCODE='23514'; END IF;
            PERFORM public.rsc_check_condition_decision_seal(COALESCE(raw->>'aggregate_id',raw->>'business_id')::uuid);
        END IF;
        SELECT array_agg(value) INTO keys FROM jsonb_each_text(raw) WHERE key=ANY(ARRAY['idempotency_key_hash','raw_key_hash','regional_key_hash','headquarters_key_hash','disposition_key_hash','return_key_hash','reversal_key_hash','approval_key_hash','correction_key_hash','recovery_key_hash','scrap_key_hash','condition_key_hash']);
        body:=COALESCE(raw->'after_jsonb',raw->'metadata_jsonb',raw->'payload_jsonb','{}'::jsonb);
        FOR matched IN SELECT s.id FROM public.stock_condition_decision_seals s
            WHERE s.key_token=raw->>'key_token' OR (s.actor_user_id=raw->>'actor_user_id' AND s.request_id=raw->>'request_id')
            OR (s.raw_key_hash=ANY(keys) OR s.regional_key_hash=ANY(keys) OR s.headquarters_key_hash=ANY(keys) OR s.disposition_key_hash=ANY(keys) OR s.return_key_hash=ANY(keys) OR s.reversal_key_hash=ANY(keys) OR s.approval_key_hash=ANY(keys) OR s.correction_key_hash=ANY(keys) OR s.recovery_key_hash=ANY(keys) OR s.scrap_key_hash=ANY(keys) OR s.condition_key_hash=ANY(keys)) OR s.id::text=raw->>'aggregate_id' OR s.id::text=raw->>'business_id'
            OR s.id::text=raw->>'source_document_id' OR s.request_id=body->>'request_id'
            OR ((s.actor_user_id=COALESCE(raw->>'actor_user_id',raw->>'actor_id')) AND raw->>'request_id'='inventory-request-'||
                encode(sha256(convert_to('cloud_oam.inventory.request.v1','UTF8')||decode('00','hex')||convert_to(s.request_id,'UTF8')),'hex'))
            OR body->>'request_reference'='inventory-request-'||encode(sha256(
                convert_to('cloud_oam.inventory.request.v1','UTF8')||decode('00','hex')||convert_to(s.request_id,'UTF8')),'hex')
        LOOP
            PERFORM public.rsc_check_condition_decision_seal(matched);
        END LOOP;
    END LOOP;
    RETURN NULL;
END $function$

