        FOR checked IN SELECT id FROM public.stock_condition_events
            WHERE case_id=checked_case
                AND kind IN ('execute','release') LOOP
            PERFORM public.rsc_condition_check_settlement_input(checked);
        END LOOP;
    END IF;
    RETURN NULL;
END $function$

