CREATE OR REPLACE FUNCTION public.rsc_register_condition_decision_seal(actor_id text, actor_version bigint, actor_person uuid, command jsonb, client_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prepared jsonb; aliases jsonb; token text; prior public.stock_condition_decision_seals%ROWTYPE;
    s public.stock_condition_decision_seals%ROWTYPE; raw jsonb;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' OR client_key IS NULL
       OR client_key !~ '^[A-Za-z0-9._:-]{8,200}$' THEN
        RAISE EXCEPTION 'condition decision seal real client key and read committed required' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'condition decision seal ledger head required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_lock_formal_principal_graph_0026(ARRAY[actor_id]::text[]);
    PERFORM 1 FROM public.audit_chain_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'condition decision seal audit head required' USING ERRCODE='23514'; END IF;
    prepared:=public.rsc_condition_decision_seal_input(command,client_key);
    SELECT jsonb_object_agg(key,value) INTO aliases FROM jsonb_each(prepared) WHERE key=ANY(ARRAY['raw_key_hash','regional_key_hash','headquarters_key_hash','disposition_key_hash','return_key_hash','reversal_key_hash','approval_key_hash','correction_key_hash','recovery_key_hash','scrap_key_hash','condition_key_hash']);
    token:=prepared->>'key_token';
    SELECT * INTO prior FROM public.stock_condition_decision_seals WHERE key_token=token
        OR (actor_user_id=actor_id AND request_id=prepared->>'request_id') ORDER BY id LIMIT 1;
    IF prior.id IS NOT NULL THEN
        IF prior.actor_user_id IS DISTINCT FROM actor_id OR prior.actor_person_id IS DISTINCT FROM actor_person
           OR prior.command_jsonb IS DISTINCT FROM command OR prior.key_token IS DISTINCT FROM token
           OR (SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(prior)) WHERE key=ANY(ARRAY['raw_key_hash','regional_key_hash','headquarters_key_hash','disposition_key_hash','return_key_hash','reversal_key_hash','approval_key_hash','correction_key_hash','recovery_key_hash','scrap_key_hash','condition_key_hash'])) IS DISTINCT FROM aliases THEN
            RAISE EXCEPTION 'condition decision sealed original request conflict' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_condition_decision_seal_authority(actor_id,actor_version,actor_person,command,false);
        PERFORM public.rsc_check_condition_decision_seal(prior.id);
        RETURN jsonb_build_object('seal',to_jsonb(prior),'created',false,'audit_payload',public.rsc_condition_decision_seal_payload(prior.id));
    END IF;
    prepared:=public.rsc_condition_decision_seal_authority(actor_id,actor_version,actor_person,command,true);
    raw:=prepared||aliases||jsonb_build_object('id',gen_random_uuid(),'created_at',clock_timestamp(),
        'actor_user_id',actor_id,'actor_person_id',actor_person,'authorization_version',actor_version,'key_token',token);
    SELECT * INTO s FROM jsonb_populate_record(NULL::public.stock_condition_decision_seals,raw);
    INSERT INTO public.stock_condition_decision_seals SELECT s.*;
